import {readFile} from 'node:fs/promises';
import {createContext,runInContext} from 'node:vm';
import assert from 'node:assert/strict';
const c=createContext({state:{active:{start:'2026-10-25T12:00:00',pauses:[],exercises:[{id:'stretch',sets:[{seconds:120,restSeconds:60,done:false},{seconds:120,done:false}]}]}},document:{addEventListener(){},querySelector(){return null}},localNow:()=> '2026-10-25T12:00:00',persist(){},toast(){},icon:s=>s,esc:s=>s});
for(const file of ['workout-pause','set-rest','set-countdown'])runInContext(await readFile(new URL(`../src/${file}.js`,import.meta.url),'utf8'),c);
runInContext(await readFile(new URL('../src/set-time.js',import.meta.url),'utf8'),c);
assert.equal(runInContext("startSetCountdown('set',0,0)",c),true);
assert.equal(runInContext("countdownRemaining(state.active.countdown,'2026-10-25T12:00:20')",c),100);
runInContext("toggleSetCountdown('set',0,0,'2026-10-25T12:00:20')",c);
assert.equal(runInContext("countdownRemaining(state.active.countdown,'2026-10-25T12:00:50')",c),100,'Individual pause freezes countdown');
runInContext("toggleSetCountdown('set',0,0,'2026-10-25T12:00:50');toggleWorkoutPause(state.active,'2026-10-25T12:01:00')",c);
assert.equal(runInContext("countdownRemaining(state.active.countdown,'2026-10-25T12:01:30')",c),90,'Workout pause freezes countdown too');
c.state.active=JSON.parse(JSON.stringify(c.state.active));
runInContext("toggleWorkoutPause(state.active,'2026-10-25T12:01:40')",c);
assert.equal(runInContext("countdownRemaining(state.active.countdown,'2026-10-25T12:01:50')",c),80,'Reload retains individual and workout pauses');
runInContext('onSetMarked(0,0,true)',c);
assert.equal(c.state.active.countdown.kind,'rest');
assert.equal(c.state.active.countdown.duration,60);
assert.equal(runInContext("countdownRemaining(state.active.countdown,'2026-10-25T12:00:30')",c),30);
assert.equal(runInContext("countdownRemaining(state.active.countdown,'2026-10-25T13:00:00')",c),0,'No negative time after backgrounding');
runInContext('onSetMarked(0,0,false)',c);
assert.equal(c.state.active.countdown,null,'Undoing check cancels its rest');
runInContext('onSetMarked(0,1,true)',c);
assert.equal(c.state.active.countdown,null,'An unrelated rest is not started');
runInContext("startSetCountdown('rest',0,0);removeSetRest(0,0)",c);
assert.equal(c.state.active.countdown,null,'Removing active rest stops its timer');
assert.equal(c.state.active.exercises[0].sets[0].seconds,120,'Countdown never overwrites prescribed duration');
console.log('Passed: set countdown, rest trigger/undo, pause/resume/reload, background expiry and preserving prescribed duration.');

// Early completion stores elapsed work, including when repetitions are filled later.
c.state.active.exercises[0].sets[0].seconds=0;
runInContext("startSetCountdown('set',0,0,'2026-10-25T14:00:00')",c);
assert.equal(c.state.active.countdown.stopwatch,true);
assert.equal(runInContext("countdownElapsed(state.active.countdown,'2026-10-25T14:00:37')",c),37);
runInContext("finishWorkTimer(0,0,'2026-10-25T14:00:37')",c);
assert.equal(c.state.active.exercises[0].sets[0].seconds,37);
assert.equal(c.state.active.countdown,null);
c.state.active.exercises[0].sets[0].restSeconds=60;
runInContext("startSetCountdown('rest',0,0,'2026-10-25T14:01:00');finishSetRest(0,0,'2026-10-25T14:01:12')",c);
assert.equal(c.state.active.countdown.elapsed,12);
assert.equal(c.state.active.countdown.finished,true);
assert.equal(c.state.active.exercises[0].sets[0].restDone,true);
assert.equal(c.state.active.exercises[0].sets[0].restSeconds,60);
assert.equal(runInContext('countdownRemaining(state.active.countdown)',c),0);
console.log('Passed: strength stopwatch, actual work time and early rest completion without changing the rest preset.');
